<section class="wrap section"><a class="text-link" href="<?=e(url('destination',['id'=>$h['destination_id']]))?>">← <?=e(t($h['destination_name']))?></a><div class="heading-row"><div><p class="eyebrow"><?=e(t($h['country_name']))?> · <?=e($h['stars'])?><?=e(t('-STAR HOTEL'))?></p><h1 class="hotel-title"><?=e($h['name'])?></h1><p><?=e(t($h['address']))?></p></div><?php save_control((int)$h['id'],true); ?></div><div class="gallery"><img class="gallery-main" src="<?=e(photo($h['image']))?>" alt="<?=e(t('Illustrative photo of this stay style'))?>"><?php foreach(array_slice($rooms,0,2) as $r): ?><img src="<?=e(photo($r['image']))?>" alt="Illustrative <?=e(t($r['name']))?> photo"><?php endforeach ?></div><div class="detail-summary"><div><p class="eyebrow"><?=e(t('A PLACE TO SETTLE IN'))?></p><h2><?=e(t('Your own'))?> <em><?=e(t('little corner.'))?></em></h2><p class="lead"><?=e(t($h['description']))?></p><p class="muted"><?=e(t('Illustrative photographs and fictional hotel details for this demonstration.'))?></p></div><div class="panel"><h3><?=e(t('The good details'))?></h3><p><?=e(t($h['facilities']))?></p><p><?=e(t('Check-in: 2:00 PM'))?><br><?=e(t('Check-out: 11:00 AM'))?></p><p><?=e(t('Cancel before check-in. Verified payments require a manual refund from the administrator.'))?></p></div></div><h2><?=e(t('Pick your'))?> <em><?=e(t('perfect room.'))?></em></h2><form class="search-bar search-inline" data-availability data-endpoint="<?=e(asset('api/availability.php'))?>" method="get" action="<?=e(url('hotel'))?>"><input type="hidden" name="id" value="<?=e($h['id'])?>"><label><span><?=e(t('CHECK IN'))?></span><input name="check_in" type="date" value="<?=e($in)?>" min="<?=$today?>" required></label><label><span><?=e(t('CHECK OUT'))?></span><input name="check_out" type="date" value="<?=e($out)?>" min="<?=$tomorrow?>" required></label><label><span><?=e(t('TRAVELERS'))?></span><select name="guests"><?php for($g=1;$g<=12;$g++): ?><option value="<?=$g?>" <?=$guests===$g?'selected':''?>><?=$g?></option><?php endfor ?></select></label><button class="button"><?=e(t('Check availability'))?></button></form><p id="availability-feedback" class="notice <?=$goodDates?'info':'error'?>" role="status" <?=$goodDates?'hidden':''?>><?=e($goodDates?'':t($dateError))?></p>
